import{_ as t,o as d,c as a,X as r}from"./chunks/framework.pSp8ynCZ.js";const u=JSON.parse('{"title":"Matrix storage: store","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-store.md","filePath":"reference-store.md"}'),o={name:"rust/api/reference-store.md"};function c(s,e,n,i,l,p){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="matrix-storage-store" tabindex="-1">Matrix storage: store <a class="header-anchor" href="#matrix-storage-store" aria-label="Permalink to &quot;Matrix storage: store&quot;">​</a></h1><p><code>cellpack::store</code> owns the file-level workflow: streaming matrix writes, prepared reads, physical read planning, and decoding into caller-owned outputs. It does not own sampling, a shared gene vocabulary, or an asynchronous training queue. For those tasks, use <a href="/cellpack-docs/rust/api/reference-loader.html">loader</a>.</p><h2 id="input-and-output-model" tabindex="-1">Input and output model <a class="header-anchor" href="#input-and-output-model" aria-label="Permalink to &quot;Input and output model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation family</th><th>Takes</th><th>Produces</th></tr></thead><tbody><tr><td>Writer</td><td>Declared matrix dtype/layout and row batches</td><td>One finalized <code>.cpk</code> matrix stream</td></tr><tr><td>File inspection</td><td>Path or embedded region</td><td>Dimensions, dtype, superblock, directory and chunk bytes</td></tr><tr><td>Prepared selection</td><td>File rows, optional source-to-output map, read policy</td><td><code>ReadSelection</code> with shape, capacity and I/O plan</td></tr><tr><td>Borrowed-output read</td><td>Selection, typed buffers, workspace, worker count</td><td>Dense values or canonical CSR plus actual nnz</td></tr><tr><td>Panel-row helper</td><td>Chunk metadata/tables, panel and mapper</td><td>Mapped rows in caller buffers</td></tr></tbody></table><p>See the shared <a href="/cellpack-docs/rust/api/contracts.html">matrix, conversion, and lifetime contracts</a>.</p><h2 id="cpkwriter" tabindex="-1">CpkWriter <a class="header-anchor" href="#cpkwriter" aria-label="Permalink to &quot;CpkWriter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Inputs</th><th>Return and postcondition</th></tr></thead><tbody><tr><td><code>create</code></td><td><code>path, n_cols, dtype, source_layout, CpkOptions</code></td><td><code>Result&lt;CpkWriter&gt;</code>; creates/truncates the path, which is not yet a valid stream</td></tr><tr><td><code>append</code></td><td>Borrowed <code>MatrixRef</code>-convertible rows</td><td><code>Result&lt;()&gt;</code>; appends in order, buffering a partial chunk</td></tr><tr><td><code>set_threads</code></td><td>Desired thread count</td><td><code>()</code>; counts below one become one; complete chunks can encode concurrently</td></tr><tr><td><code>end_chunk</code></td><td>Writer&#39;s staged rows</td><td><code>Result&lt;()&gt;</code>; flushes them so the next append starts a new chunk</td></tr><tr><td><code>append_packed</code></td><td>One encoded and page-packed chunk</td><td><code>Result&lt;()&gt;</code>; appends without re-encoding after compatibility checks</td></tr><tr><td><code>finish</code></td><td>Consumes writer</td><td><code>Result&lt;()&gt;</code>; writes tail, directory and final superblock</td></tr></tbody></table><p><code>append</code> requires matching column count and value width. If the incoming form differs from the declared source layout, the writer converts CSR/dense form. CSR columns remain canonical. <code>append_packed</code> requires no staged rows and a chunk with matching dimensions, value width, page size and total byte length.</p><p><code>CpkOptions::new(encode)</code> defaults to 4096 rows per chunk and 4096-byte pages. <code>chunk_rows</code> is a target; early chunk endings and appended packed chunks may produce different chunk lengths. Codec choices live in <a href="/cellpack-docs/rust/api/reference-scans.html">EncodeOptions</a>.</p><h2 id="cpkfile" tabindex="-1">CpkFile <a class="header-anchor" href="#cpkfile" aria-label="Permalink to &quot;CpkFile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Inputs</th><th>Return</th></tr></thead><tbody><tr><td><code>open</code></td><td>Path</td><td>Opened matrix handle</td></tr><tr><td><code>open_region</code></td><td>Path, byte offset, optional bounded byte length</td><td>Handle to an embedded stream</td></tr><tr><td><code>n_rows / n_cols / dtype</code></td><td>Handle</td><td>Matrix shape and stored type</td></tr><tr><td><code>superblock / chunks</code></td><td>Handle</td><td>Borrowed stream metadata and directory entries</td></tr><tr><td><code>byte_offset</code></td><td>Handle</td><td>Stream&#39;s offset in its outer file</td></tr><tr><td><code>identity</code></td><td>Open descriptor</td><td>Device and inode, independent of later path replacement</td></tr><tr><td><code>read_meta / read_chunk</code></td><td>Chunk index</td><td>Owned metadata bytes or complete chunk bytes</td></tr><tr><td><code>read_chunk_into</code></td><td>Chunk index, metadata-only flag, exact-size byte buffer</td><td>Writes chunk bytes into the supplied buffer</td></tr><tr><td><code>read_dense / read_csr</code></td><td>Half-open <code>Range&lt;u64&gt;</code></td><td>Allocated stored-dtype bytes or <code>Csr</code></td></tr><tr><td><code>prepare_read</code></td><td>Half-open row range</td><td>Prepared selection of every source column</td></tr><tr><td><code>prepare_selection</code></td><td><code>RowSelection</code>, optional map, output width, <code>ReadOptions</code></td><td>Prepared ordered selection</td></tr></tbody></table><p><code>open_region</code> interprets format offsets relative to the stream. <code>read_dense</code> returns <code>Vec&lt;u8&gt;</code>, not <code>Vec&lt;f32&gt;</code>. Allocated <code>Csr</code> stores <code>u64</code> offsets, <code>u32</code> indices and value bytes. Obtain its value dtype and source column count from the file; <code>Csr</code> has no dtype/shape fields. Prepared typed reads are the route for conversion or buffer reuse.</p><h2 id="readselection-and-readworkspace" tabindex="-1">ReadSelection and ReadWorkspace <a class="header-anchor" href="#readselection-and-readworkspace" aria-label="Permalink to &quot;ReadSelection and ReadWorkspace&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Inputs</th><th>Output and mutation</th></tr></thead><tbody><tr><td><code>spec</code></td><td>Prepared selection</td><td><code>ReadSpec { rows, columns, nnz, dtype }</code></td></tr><tr><td><code>io_summary</code></td><td>Prepared physical reads</td><td>Planned payload/read bytes and request counts</td></tr><tr><td><code>read_dense_into&lt;T&gt;</code></td><td>Exact <code>rows × columns</code> buffer, exclusive workspace, workers</td><td><code>Result&lt;()&gt;</code>; fills every output element</td></tr><tr><td><code>read_csr_into&lt;P,I,T&gt;</code></td><td>Exact row-offset array, index/value capacities, workspace, workers</td><td><code>Result&lt;usize&gt;</code>; returns actual nnz and canonical output indices</td></tr><tr><td><code>ReadWorkspace::clear</code></td><td>Workspace</td><td>Releases retained scratch</td></tr></tbody></table><p><code>RowSelection::Range</code> uses half-open file rows. <code>List</code> preserves arbitrary order and repetitions. The optional map covers every source column, maps kept columns to distinct output positions, and uses <code>UNMAPPED</code> for drops. Missing output positions are zero. Without a map, output width must equal file width.</p><p><code>ReadSpec::dense_len</code> is an element count; <code>dense_bytes</code> and <code>value_bytes</code> use the stored dtype width, not a requested converted output type. Allocate typed output using element counts and <code>size_of::&lt;T&gt;()</code>. <code>nnz</code> is capacity, not post-filter actual nnz. Narrow index types must hold the largest output column and every needed row offset.</p><p>Preparing a selection reads metadata. Each read invocation performs record I/O. The selection owns its prepared state; output is owned by the caller. Concurrent reads need separate mutable workspaces and outputs. Failures can leave partial writes.</p><h2 id="physical-reads-and-panel-helpers" tabindex="-1">Physical reads and panel helpers <a class="header-anchor" href="#physical-reads-and-panel-helpers" aria-label="Permalink to &quot;Physical reads and panel helpers&quot;">​</a></h2><p><code>RecordReadPlan::new(meta, cells, options)</code> plans one chunk&#39;s records from metadata. <code>ranges</code> returns disjoint read ranges; <code>summary</code> returns byte/request totals. <code>read_into(file, base, out)</code> resizes a byte vector and reads each range relative to the records-region <code>base</code>. <code>record(out, position)</code> returns a borrowed record slice for the corresponding requested position, including repeated/empty records.</p><p><code>ReadOptions</code> defaults to <code>Auto</code>, zero merge gap, and 4096 equivalent bytes per request. <code>WholeChunk</code> means the complete records region, excluding metadata. <code>ReadSummary</code> describes application reads, not physical device traffic.</p><p><code>compose_panel</code> combines a chunk permutation and an optional source map. <code>PanelRows&lt;S,T&gt;</code> binds metadata, tables, a panel and a mapper; <code>bind</code> prepares <code>RowScratch&lt;T&gt;</code>; <code>dense</code> and <code>csr</code> decode/map individual records. These helpers share the codec&#39;s trusted-record contract. Returned CSR column slices borrow scratch and must be consumed before its reuse.</p><h2 id="complete-interface-index" tabindex="-1">Complete interface index <a class="header-anchor" href="#complete-interface-index" aria-label="Permalink to &quot;Complete interface index&quot;">​</a></h2><p>Each entry opens a searchable page with its declaration, parameter/return types, fields, methods, and source documentation.</p><h3 id="structs" tabindex="-1">Structs <a class="header-anchor" href="#structs" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-CpkFile.html"><code>CpkFile</code></a></td><td>An opened .cpk file.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-CpkOptions.html"><code>CpkOptions</code></a></td><td>How a file is chunked and coded.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-CpkWriter.html"><code>CpkWriter</code></a></td><td>Writes one matrix to a .cpk file. Rows are appended in order; the file is valid only after CpkWriter::finish .</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-Csr.html"><code>Csr</code></a></td><td>Owned CSR rows with ascending source column ids within each row. Values are little-endian bytes interpreted with CpkFile::dtype ; this object does not carry a separate dtype or shape descriptor.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-PanelRows.html"><code>PanelRows</code></a></td><td>Decodes records of one chunk into panel rows of T , reading stored values as S (the chunk’s value width).</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-ReadOptions.html"><code>ReadOptions</code></a></td><td>Read planning: strategy, merge threshold and the estimated cost of a read.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-ReadRange.html"><code>ReadRange</code></a></td><td>One read: length bytes at offset (from the records region start) land at buffer_offset in the read buffer.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-ReadSelection.html"><code>ReadSelection</code></a></td><td>Metadata prepared once for repeated reads into independently owned outputs. spec().nnz is the CSR capacity: the stored entries of the selected cells, which dropped genes can reduce in the result.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-ReadSpec.html"><code>ReadSpec</code></a></td><td>Output dimensions of a prepared selection: nnz is the CSR capacity and dtype the stored dtype.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-ReadSummary.html"><code>ReadSummary</code></a></td><td>I/O a plan performs, counted in bytes and requests.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-ReadWorkspace.html"><code>ReadWorkspace</code></a></td><td>Reusable private scratch: per-thread decode buffers by output element type and the row bookkeeping of CSR reads. It never holds outputs; one workspace serves one read at a time.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-RecordReadPlan.html"><code>RecordReadPlan</code></a></td><td>Reads for a list of cells and the buffer slice each cell’s record occupies.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-RowScratch.html"><code>RowScratch</code></a></td><td>Private per-thread scratch for PanelRows and file selections. It grows on demand, is reusable across chunks and never holds outputs.</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-store-enum-ReadStrategy.html"><code>ReadStrategy</code></a></td><td>When to read the whole records region instead of the selected ranges.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-enum-RowSelection.html"><code>RowSelection</code></a></td><td>Cells to read: a contiguous range, or a gather in output order whose ids may repeat.</td></tr></tbody></table><h3 id="traits" tabindex="-1">Traits <a class="header-anchor" href="#traits" aria-label="Permalink to &quot;Traits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-store-trait-OutputElement.html"><code>OutputElement</code></a></td><td>Element types a selection reads into, from any stored dtype.</td></tr></tbody></table><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-store-fn-compose_panel.html"><code>compose_panel</code></a></td><td>Composes a chunk’s coded gene order with a source → panel map (identity when None ) into out , indexed by coded id.</td></tr></tbody></table>',31)])])}const m=t(o,[["render",c]]);export{u as __pageData,m as default};
